    /**
     * Method to retrieve the Refund via RefundFetchOneSummary
     * @param 	summary RefundFetchOneSummary 
     * @return 	RefundFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Refund getRefund( RefundFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "RefundFetchOneSummary arg cannot be null" );
    	
    	Refund entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Refund
        	// --------------------------------------
        	CompletableFuture<Refund> futureEntity = queryGateway.query(new FindRefundQuery( new LoadRefundFilter( summary.getRefundId() ) ), ResponseTypes.instanceOf(Refund.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Refund with id " + summary.getRefundId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


