    /**
     * assign Payment on Refund
     * @param		command AssignPaymentToRefundCommand	
     * @exception	ProcessingException
     */     
	public void assignPayment( AssignPaymentToRefundCommand command ) throws ProcessingException {

		// --------------------------------------------
		// load the parent
		// --------------------------------------------
		load( command.getRefundId() );
		
		PaymentService childDelegate 	= PaymentService.getPaymentInstance();
		RefundService parentDelegate = RefundService.getRefundInstance();			
		UUID childId = command.getAssignment().getPaymentId();
		Payment child = null;
		
		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	validator.validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );

		}
        catch( Throwable exc ) {
			final String msg = "Failed to get Payment using id " + childId;
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

